  }).formatToParts(parseIso(value));
  const part = (name: string) => parts.find((p) => p.type === name)"'!.value;
  return `${part("year")}-${part("month")}-${part("day")}`;
}

function localParts(date: Date, timeZone: string): number[] {
  const parts = new Intl.DateTimeFormat("en-GB", {
    timeZone, year: "numeric", month: "2-digit", day: "2-digit",
    hour: "2-digit", minute: "2-digit", second: "2-digit", hourCycle: "h23",
  }).formatToParts(date);
  return ["year", "month", "day", "hour", "minute", "second"].map(
    (name) => Number(parts.find((p) => p.type === name)!.value),
  );
}

// Resolve a wall time using nearby offsets. For repeated times choose the first
// occurrence; for skipped times move forward by the size of the gap.
function wallTime(day: string, hour: number, timeZone: string): Date {
  const [year, month, date] = day.split("-").map(Number);
  const target = Date.UTC(year, month - 1, date, hour);
  const offsets = new Set<number>();
  for (const delta of [-48, -24, 0, 24, 48]) {
    const sample = target + delta * HOUR_MS;
    const [y, m, d, h, min, sec] = localParts(new Date(sample), timeZone);
    offsets.add(Date.UTC(y, m - 1, d, h, min, sec) - sample);
  }
  const candidates = [...offsets].map((offset) => target - offset);
  const wall = (instant: number) => {
    const [y, m, d, h, min, sec] = localParts(new Date(instant), timeZone);
    return Date.UTC(y, m - 1, d, h, min, sec);
  };
  const exact = candidates.filter((instant) => wall(instant) === target);
  if (exact.length) return new Date(Math.min(...exact));
  const after = candidates.filter((instant) => wall(instant) > target);
  return new Date(after.sort((a, b) => wall(a) - wall(b))[0]);
}

export function shiftLocalDate(day: string, days: number): string {
  const date = new Date(`${day}T00:00:00.000Z`);
  date.setUTCDate(date.getUTCDate() + days);
  return date.toISOString().slice(0, 10);
}

export function startOfLocalDay(reference: Date, timeZone: string): IsoTimestamp {
  return toIsoTimestamp(wallTime(localDate(toIsoTimestamp(reference), timeZone), 0, timeZone));
}

export function isOverdue(
  dueAt: IsoTimestamp | null,
  reference: Date = new Date(),
  timeZone = "UTC",
): boolean {
  if (dueAt === null) return false;
  return localDate(dueAt, timeZone) < localDate(toIsoTimestamp(reference), timeZone);
}

'"'''+s[end:]; start=s.index('/**\\n * The 24-hour window'); s=s[:start]+'''/** Window between consecutive scheduled local hours. */
export function digestWindow(
